fn product(a: &Vec<u32>, b: &Vec<u32>) -> Vec<u32> {
    // Both `a` and `b` must have the same length.
    assert_eq!(a.len(), b.len());

    // Compute element-wise products.
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| x * y)
     .collect()
}

